// https://emojibase.dev version 17.0.0

const b4a = require('b4a')
const { hostToLE16 } = require('convert-endianness')

const INDEX = b4a.from('', 'base64')

exports.TAG_COUNT = 3638

exports.TAG_STR_OFFSETS = to16(0, 7278)
exports.POSTING_OFFSETS = to16(7278, 14556)
exports.POSTINGS = to16(14556, 34980)
exports.TAG_STRINGS = INDEX.subarray(34980, 56218)

function to16 (offset, end) {
  const arr = new Uint16Array(INDEX.buffer, offset, (end - offset) / 2)
  hostToLE16(arr)
  return arr
}
